import{_ as e,r as s,o,c,e as n,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"闪存消息 - October CMS - 3.x","titleTemplate":false,"description":"显示关于请求结果的消息。","frontmatter":{"subtitle":"显示关于请求结果的消息。"},"headers":[{"level":2,"title":"内置闪存消息","slug":"内置闪存消息","link":"#内置闪存消息","children":[{"level":3,"title":"加载闪存消息","slug":"加载闪存消息","link":"#加载闪存消息","children":[]},{"level":3,"title":"自定义闪存消息样式","slug":"自定义闪存消息样式","link":"#自定义闪存消息样式","children":[]}]},{"level":2,"title":"自定义闪存消息","slug":"自定义闪存消息","link":"#自定义闪存消息","children":[]},{"level":2,"title":"使用 JavaScript","slug":"使用-javascript","link":"#使用-javascript","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/cms/features/flash-messages.md","filePath":"3.x/zh-cn/cms/features/flash-messages.md"}'),i={name:"3.x/zh-cn/cms/features/flash-messages.md"};function r(k,a,g,d,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[n(t),a[0]||(a[0]=l("h1",null,"闪存消息",-1)),n(p),a[1]||(a[1]=u(`<p>闪存消息是一种方便的方式，用于告知用户请求的结果，无论是成功还是失败。只需使用 <code>Flash</code> 门面在请求完成后显示消息。闪存消息通常设置在 <a href="./../ajax/handlers.html">AJAX 处理程序</a> 内、<a href="./../../extend/cms-components.html">组件逻辑</a> 内，或页面或布局的 <a href="./../themes/themes.html">PHP 部分</a> 内。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSave</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Sets a successful message</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Settings successfully saved!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Sets an error message</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Something went wrong...&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Sets a warning message</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">warning</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Please confirm your email address soon&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Sets an informative message</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;The export is still processing. Please try again in a minute.&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>闪存消息将在 3 秒间隔后消失。点击闪存消息将阻止其消失。</p><h2 id="内置闪存消息"><a href="#内置闪存消息" class="header-anchor">#</a> 内置闪存消息</h2><p>AJAX 框架内置了对闪存消息的支持，只需在表单上指定 <code>data-request-flash</code> 属性即可在已完成的 AJAX 请求上启用闪存消息。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSuccess<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-flash</span><span class="token punctuation">&gt;</span></span>
    <span class="token comment">&lt;!-- ... --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>为确保在浏览器重定向时也能显示闪存消息，你应该在页面加载时渲染<a href="./../../markup/tag/flash.html">内联闪存消息</a>，方法是将以下代码放在你的页面或布局中。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span>
        <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flash-message<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> type <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-interval</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>5<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>要仅显示特定类型的闪存消息，你可以将值传递给属性 &amp;mdash; <strong>success</strong>、<strong>error</strong>、<strong>info</strong>、<strong>warning</strong> 或 <strong>validate</strong>。多个值用逗号分隔。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request-flash</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>success,warning<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>当 <code>data-request-flash</code> 属性与<a href="./validation.html">验证功能</a>结合使用时，验证错误会优先显示并抑制闪存消息。要同时显示两者，请在属性中包含 <strong>validate</strong> 类型。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
    <span class="token attr-name">data-request-validate</span>
    <span class="token attr-name">data-request-flash</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>success,error,validate<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="加载闪存消息"><a href="#加载闪存消息" class="header-anchor">#</a> 加载闪存消息</h3><p><code>data-request-message</code> 属性可用于在请求运行时显示闪存进度消息。这对于长时间运行的过程特别有用。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmit<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Please wait while we process your request...<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Submit
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="自定义闪存消息样式"><a href="#自定义闪存消息样式" class="header-anchor">#</a> 自定义闪存消息样式</h3><p>要更改闪存消息的外观，请使用 <code>.oc-flash-message</code> CSS 类作为目标。</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">.oc-flash-message.success</span> <span class="token punctuation">{</span>
    <span class="token property">background</span><span class="token punctuation">:</span> green<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token selector">.oc-flash-message.error</span> <span class="token punctuation">{</span>
    <span class="token property">background</span><span class="token punctuation">:</span> red<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token selector">.oc-flash-message.warning</span> <span class="token punctuation">{</span>
    <span class="token property">background</span><span class="token punctuation">:</span> orange<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token selector">.oc-flash-message.info</span> <span class="token punctuation">{</span>
    <span class="token property">background</span><span class="token punctuation">:</span> aqua<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token selector">.oc-flash-message.loading</span> <span class="token punctuation">{</span>
    <span class="token property">background</span><span class="token punctuation">:</span> aqua<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="自定义闪存消息"><a href="#自定义闪存消息" class="header-anchor">#</a> 自定义闪存消息</h2><div class="custom-block aside"><p>查看<a href="./../../markup/tag/flash.html">闪存 Twig 标签文章</a>了解更多关于 <code>{% flash %}</code> 标签的信息。</p></div><p>要显示内联闪存消息或完全更改默认闪存消息标记，请在你的主题中创建一个包含自定义内容的新部件。例如，创建一个名为 <strong>flash-messages.htm</strong> 的新部件并粘贴以下内容。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> type <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>接下来，使用 <code>{% ajaxPartial %}</code> 标签将该部件作为<a href="./../../markup/tag/ajax-partial.html">自更新部件</a>包含在你的表单中。在 <code>data-request-update</code> 中引用部件名称将自动更新此部件并禁用内置的闪存消息。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>flash-messages<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Title<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>title<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ flash-messages: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Save
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>或者，你可以将部件包含在布局中，并全局更新它，而不是在每个元素上添加 <code>data-request-flash</code>。在页面的 head 部分添加 <code>ajax-request-update</code> meta 标签，并将 content 属性设置为<a href="./../ajax/update-partials.html">全局更新部件</a>。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ajax-request-update<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ flash-messages: true }<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    <span class="token comment">&lt;!-- Updates with every AJAX request --&gt;</span>
    {% ajaxPartial &#39;flash-messages&#39; %}
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="使用-javascript"><a href="#使用-javascript" class="header-anchor">#</a> 使用 JavaScript</h2><p>使用 <code>oc.flashMsg</code> 函数通过 JavaScript 显示闪存消息。类型可以指定为 <code>success</code>、<code>error</code> 或 <code>warning</code>。可以指定一个可选的 <code>interval</code> 来控制闪存消息显示的时长（以秒为单位）。</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">flashMsg</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
    <span class="token literal-property property">message</span><span class="token operator">:</span> <span class="token string">&#39;Record has been successfully saved. This message will disappear in 1 second.&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&#39;success&#39;</span><span class="token punctuation">,</span>
    <span class="token literal-property property">interval</span><span class="token operator">:</span> <span class="token number">1</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/flash.html">闪存 Twig 标签</a></li></ul></div>`,31))])}const q=e(i,[["render",r]]);export{v as __pageData,q as default};
